# --- 테스트에 now() 가 있으면 ---

@DisplayName("결제 완료 주문의 매출 통계 메일을 보낸다")
@Test
void sendOrderStatisticsMail() {
    // given
    createPaymentCompletedOrder(LocalDateTime.now());

    // when
    boolean result = orderStatisticsService.sendOrderStatisticsMail(
            LocalDate.now(), "admin@cafekiosk.com");

    // then
    assertThat(result).isTrue();
}

