# --- 그리고 경계를 짤 수 있다 ---

@DisplayName("자정 1초 전 주문은 그날 통계에 포함된다")
@Test
void orderJustBeforeMidnight() {
    createPaymentCompletedOrder(LocalDateTime.of(2026, 9, 9, 23, 59, 59));

    boolean result = orderStatisticsService.sendOrderStatisticsMail(
            LocalDate.of(2026, 9, 9), "admin@cafekiosk.com");

    assertThat(result).isTrue();
    assertThat(mailSendHistoryRepository.findAll())
            .extracting("content").containsExactly("총 매출: 4000");
}

@DisplayName("자정 정각 주문은 다음날 통계에 포함된다")
@Test
void orderAtMidnight() {
    createPaymentCompletedOrder(LocalDateTime.of(2026, 9, 10, 0, 0, 0));

    orderStatisticsService.sendOrderStatisticsMail(
            LocalDate.of(2026, 9, 9), "admin@cafekiosk.com");

    assertThat(mailSendHistoryRepository.findAll())
            .extracting("content").containsExactly("총 매출: 0");
}

